cat > /tmp/bot-check/check.mjs <<'EOF'
import { mkdtemp, writeFile, utimes, mkdir, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import assert from 'node:assert/strict';

const run = promisify(execFile);
const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g4-3/bot.mjs';
const dir = await mkdtemp(path.join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = dir;
const { reserve, release } = await import(BOT);

const H = 3600e3, M = 60e3;
const T = Date.parse('2026-10-22T10:00:00Z');
const req = (over = {}) => ({ userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 0, ...over });
const at = (ms) => new Date(ms);
let passed = 0;
const test = async (name, fn) => { await fn(); passed++; console.log('ok -', name); };

// Child process: simulates a separate worker, with its own process and module instance.
async function child(op, a, b) {
  const { stdout } = await run('node', ['/tmp/bot-check/worker.mjs', op, a, b === undefined ? '' : String(b)], { env: { ...process.env, STATE_DIR: dir } });
  return JSON.parse(stdout);
}

await test('window limit: 3 allowed in 24h, 4th denied with snake_case reason', async () => {
  for (let i = 0; i < 3; i++) {
    const r = await reserve(req(), at(T + i * M));
    assert.equal(r.allowed, true); assert.equal(r.reason, null); assert.match(r.reservationId, /^[0-9a-f]{64}\.[0-9a-f-]{36}$/);
  }
  const r = await reserve(req(), at(T + 10 * M));
  assert.deepEqual(r, { allowed: false, reason: 'window_limit_reached', reservationId: null });
});

await test('denied attempts are not recorded (retrying does not extend the block)', async () => {
  // After the window slides past the first send, a slot opens even though we retried a lot.
  for (let i = 0; i < 20; i++) await reserve(req(), at(T + 11 * M + i));
  const r = await reserve(req(), at(T + 24 * H + 1));
  assert.equal(r.allowed, true);
});

await test('sliding window: a slot reopens exactly when the oldest send leaves the window', async () => {
  const d = 'sliding';
  process.env.STATE_DIR = await mkdtemp(path.join(tmpdir(), 'bot-slide-'));
  const r1 = await reserve(req({ maxPerWindow: 2 }), at(T));
  const r2 = await reserve(req({ maxPerWindow: 2 }), at(T + H));
  assert.equal(r1.allowed && r2.allowed, true);
  assert.equal((await reserve(req({ maxPerWindow: 2 }), at(T + 23 * H))).reason, 'window_limit_reached');
  assert.equal((await reserve(req({ maxPerWindow: 2 }), at(T + 24 * H))).reason, 'window_limit_reached'); // T is exactly 24h old: still "in" (start is exclusive of now-24h only after)
  assert.equal((await reserve(req({ maxPerWindow: 2 }), at(T + 24 * H + 1))).allowed, true);
  process.env.STATE_DIR = dir;
});

await test('min gap: blocked inside gap, allowed at exactly the gap; applies both directions', async () => {
  const dd = await mkdtemp(path.join(tmpdir(), 'bot-gap-'));
  process.env.STATE_DIR = dd;
  const g = req({ maxPerWindow: 10, minGapMinutes: 90 });
  assert.equal((await reserve(g, at(T))).allowed, true);
  assert.equal((await reserve(g, at(T + 60 * M))).reason, 'min_gap_not_elapsed');
  assert.equal((await reserve(g, at(T - 60 * M))).reason, 'min_gap_not_elapsed'); // out-of-order clock
  assert.equal((await reserve(g, at(T + 90 * M))).allowed, true);
  process.env.STATE_DIR = dir;
});

await test('limits are per call and per lead', async () => {
  assert.equal((await reserve(req({ userId: 'lead_999' }), at(T))).allowed, true);
  assert.equal((await reserve(req({ maxPerWindow: 0 }), at(T))).reason, 'window_limit_reached');
});

await test('release frees the slot and is idempotent', async () => {
  const dd = await mkdtemp(path.join(tmpdir(), 'bot-rel-'));
  process.env.STATE_DIR = dd;
  const r = [];
  for (let i = 0; i < 3; i++) r.push(await reserve(req(), at(T + i)));
  assert.equal((await reserve(req(), at(T + 5))).reason, 'window_limit_reached');
  assert.equal(await release(r[0].reservationId), true);
  assert.equal(await release(r[0].reservationId), false);   // second release does not free another slot
  assert.equal((await reserve(req(), at(T + 6))).allowed, true);
  assert.equal((await reserve(req(), at(T + 7))).reason, 'window_limit_reached');
  assert.equal(await release('not-a-valid-id'), false);
  assert.equal(await release(null), false);
  process.env.STATE_DIR = dir;
});

await test('release from a different process works, and the state survives restart', async () => {
  const dd = await mkdtemp(path.join(tmpdir(), 'bot-xproc-'));
  process.env.STATE_DIR = dd;
  const r = await reserve(req({ maxPerWindow: 1 }), at(T));
  assert.equal(r.allowed, true);
  // another process (fresh module, as after a restart) sees the slot as used
  const seen = await child('reserve', JSON.stringify(req({ maxPerWindow: 1 })), T + 1);
  assert.equal(seen.reason, 'window_limit_reached');
  // another process releases it
  assert.equal(await child('release', r.reservationId), true);
  const after = await child('reserve', JSON.stringify(req({ maxPerWindow: 1 })), T + 2);
  assert.equal(after.allowed, true);
  process.env.STATE_DIR = dir;
});

await test('concurrent workers: 12 processes at once, maxPerWindow 3 → exactly 3 allowed', async () => {
  const dd = await mkdtemp(path.join(tmpdir(), 'bot-conc-'));
  process.env.STATE_DIR = dd;
  const results = await Promise.all(Array.from({ length: 12 }, () => child('reserve', JSON.stringify(req({ userId: 'hot_lead' })), T)));
  assert.equal(results.filter((r) => r.allowed).length, 3, JSON.stringify(results));
  assert.ok(results.filter((r) => !r.allowed).every((r) => r.reason === 'window_limit_reached'));
  process.env.STATE_DIR = dir;
});

await test('concurrent workers with min gap → exactly 1 allowed', async () => {
  const dd = await mkdtemp(path.join(tmpdir(), 'bot-conc2-'));
  process.env.STATE_DIR = dd;
  const results = await Promise.all(Array.from({ length: 12 }, () => child('reserve', JSON.stringify(req({ userId: 'hot2', minGapMinutes: 90, maxPerWindow: 10 })), T)));
  assert.equal(results.filter((r) => r.allowed).length, 1, JSON.stringify(results));
  process.env.STATE_DIR = dir;
});

await test('in-process concurrency: 30 parallel reserve calls → exactly 3 allowed', async () => {
  const dd = await mkdtemp(path.join(tmpdir(), 'bot-par-'));
  process.env.STATE_DIR = dd;
  const results = await Promise.all(Array.from({ length: 30 }, () => reserve(req({ userId: 'p' }), at(T))));
  assert.equal(results.filter((r) => r.allowed).length, 3);
  process.env.STATE_DIR = dir;
});

await test('stale lock left by a dead worker is broken', async () => {
  const dd = await mkdtemp(path.join(tmpdir(), 'bot-stale-'));
  process.env.STATE_DIR = dd;
  const { createHash } = await import('node:crypto');
  const key = createHash('sha256').update('stuck', 'utf8').digest('hex');
  await mkdir(path.join(dd, 'locks'), { recursive: true });
  await mkdir(path.join(dd, 'locks', `${key}.lock`));
  const old = new Date(Date.now() - 60e3);
  await utimes(path.join(dd, 'locks', `${key}.lock`), old, old);
  const r = await reserve(req({ userId: 'stuck' }), at(T));
  assert.equal(r.allowed, true);
  process.env.STATE_DIR = dir;
});

await test('corrupt history throws (fails closed), invalid input throws', async () => {
  const dd = await mkdtemp(path.join(tmpdir(), 'bot-bad-'));
  process.env.STATE_DIR = dd;
  const { createHash } = await import('node:crypto');
  const key = createHash('sha256').update('broken', 'utf8').digest('hex');
  await mkdir(path.join(dd, 'leads'), { recursive: true });
  await writeFile(path.join(dd, 'leads', `${key}.json`), '{"half":');
  await assert.rejects(reserve(req({ userId: 'broken' }), at(T)));
  await assert.rejects(reserve(req({ userId: '' }), at(T)));
  await assert.rejects(reserve(req({ windowHours: 0 }), at(T)));
  await assert.rejects(reserve(req({ maxPerWindow: 1.5 }), at(T)));
  await assert.rejects(reserve(req(), 1234));
  process.env.STATE_DIR = dir;
});

await test('no temp files left behind after normal operation', async () => {
  const files = await readdir(path.join(dir, 'leads'));
  assert.ok(files.every((f) => f.endsWith('.json')), files.join(','));
  assert.deepEqual(await readdir(path.join(dir, 'locks')), []);
});

console.log(`\n${passed} tests passed`);
